func (b *Bus) loop() {
    subs := map[string][]chan Event{}
    for ev := range b.in {
        for _, ch := range subs[ev.Topic] {
            select {
            case ch <- ev:      // fan-out
            default:            // subscriber is full: drop instead of stalling the hub
            }
        }
    }
}
// subscribe: register a buffered chan Event over a control channel; unsubscribe: close it
